/*
 * GENERATED FILE - do not hand-edit.
 *
 * Collision footprints for scenery, mirrored from the server's Data/objectSize.cfg.
 * The client normally sizes objects from loc.dat via ObjectDef.anInt744/anInt761, but that
 * data has no size for most scenery, so the client would disagree with the server about
 * ~2229 objects. Class11 builds collision from whichever numbers it is handed, so the
 * collision call sites apply these footprints instead - while ObjectDef.anInt744/anInt761
 * keep their cache values, so model centring is untouched.
 *
 * Regenerate after editing Data/objectSize.cfg:
 *     powershell -ExecutionPolicy Bypass -File tools/generate-object-collision-sizes.ps1
 */
public final class ObjectCollisionSizes
{

	/** Highest object id in the table. */
	private static final int MAX_ID = 14209;

	/**
	 * One hex byte per object id, indexed by id. 0 means "the table has no entry";
	 * otherwise the byte is (width << 4) | height, both at least 1. Hex rather than Base64
	 * because the client targets Java 7, where java.util.Base64 does not exist.
	 */
	private static final String PACKED = ""
		+ ""
		+ ""
		+ ""
		+ ""
		+ ""
		+ ""
		+ ""
		+ ""
		;

	/** Decoded lazily on first collision lookup; one byte per id. */
	private static byte[] table;

	private ObjectCollisionSizes()
	{
	}

	private static synchronized byte[] table()
	{
		if (table != null)
			return table;
		byte[] decoded = new byte[MAX_ID + 1];
		int count = PACKED.length() / 2;
		for (int i = 0; i < count && i < decoded.length; i++)
		{
			int high = Character.digit(PACKED.charAt(i * 2), 16);
			int low = Character.digit(PACKED.charAt(i * 2 + 1), 16);
			decoded[i] = (byte) ((high << 4) | low);
		}
		table = decoded;
		return table;
	}

	/** The packed byte for an id, or 0 when the table has no entry. */
	private static int packed(int objectId)
	{
		byte[] t = table();
		if (objectId < 0 || objectId >= t.length)
			return 0;
		return t[objectId] & 0xff;
	}

	/** True when the table carries an explicit footprint for this object. */
	public static boolean has(int objectId)
	{
		return packed(objectId) != 0;
	}

	/** Footprint width for the collision map, or the caller's loc.dat size when absent. */
	public static int width(int objectId, int fallback)
	{
		int p = packed(objectId);
		return p == 0 ? fallback : (p >> 4);
	}

	/** Footprint height for the collision map, or the caller's loc.dat size when absent. */
	public static int height(int objectId, int fallback)
	{
		int p = packed(objectId);
		return p == 0 ? fallback : (p & 0xf);
	}
}
